import{_ as e,o as a,c as o,a2 as s}from"./chunks/framework.BI-oZTPy.js";const g=JSON.parse('{"title":"App settings","description":"","frontmatter":{},"headers":[],"relativePath":"app.md","filePath":"app.md"}'),n={name:"app.md"};function i(r,t,l,d,h,p){return a(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="app-settings" tabindex="-1">App settings <a class="header-anchor" href="#app-settings" aria-label="Permalink to &quot;App settings&quot;">​</a></h1><h2 id="window-and-tray" tabindex="-1">Window and tray <a class="header-anchor" href="#window-and-tray" aria-label="Permalink to &quot;Window and tray&quot;">​</a></h2><p><strong>Settings, Interface</strong>:</p><ul><li><strong>Closing the window keeps Gameyfin running</strong>: the close button hides the window to the tray. Downloads run inside the app, so without this, closing the window stops them.</li><li><strong>Start hidden in the tray</strong>. Opening Gameyfin again brings the window to the front.</li><li><strong>Start Gameyfin when I log in</strong>: starts hidden, so background downloads keep going.</li><li><strong>Bring Gameyfin back when a game closes</strong> (on by default): raises the window once a game quits, where its save upload and any error are shown.</li><li><strong>Appearance</strong>: dark, light or match your system.</li></ul><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>Three switches: downloads and installs, failures, and new versions of Gameyfin. Failures are always shown; the others stay quiet while you are looking at the window.</p><p>Clicking a notification opens Gameyfin on the page it is about. Every notification is also listed behind the bell in the title bar, even when its popup was switched off or held back. Click one to go to its page, dismiss it, or <strong>Dismiss all</strong>. The list clears when Gameyfin closes.</p><h2 id="offline" tabindex="-1">Offline <a class="header-anchor" href="#offline" aria-label="Permalink to &quot;Offline&quot;">​</a></h2><p>If the server cannot be reached, a banner says so and the library shows what is on this PC. Installed games stay playable. Everything refreshes when the server is back.</p><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h2><p>Gameyfin checks GitHub once at startup (switch off in <strong>Settings, About</strong>). What happens next depends on how you installed it:</p><table tabindex="0"><thead><tr><th>Install</th><th>Updates</th></tr></thead><tbody><tr><td>Windows <code>.exe</code></td><td>Gameyfin downloads and applies the update itself.</td></tr><tr><td>Flatpak</td><td>Updates come from the Flatpak repository; the button runs the same update.</td></tr><tr><td><code>.deb</code>, <code>.rpm</code></td><td>Your package manager owns the files, so Gameyfin only tells you a new version exists.</td></tr></tbody></table><h2 id="account" tabindex="-1">Account <a class="header-anchor" href="#account" aria-label="Permalink to &quot;Account&quot;">​</a></h2><p><strong>Settings, Account</strong> shows the server, who you are signed in as and the connection status. It also holds <strong>This device&#39;s name</strong>, shown beside every save this PC uploads, and <strong>Sign out</strong>.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Settings, Diagnostics</strong>:</p><ul><li><strong>Log files</strong>: one per day. Attach the newest when reporting a problem.</li><li><strong>Log detail</strong>: set it to Debug while reproducing a problem.</li><li><strong>App data</strong>: settings, session and local records.</li><li><strong>Artwork cache</strong>: cleans itself, or press <strong>Clear</strong> if covers look wrong.</li><li><strong>Reset settings</strong>: puts every setting back to its default. Your server, sign-in, games folders, save location and per-game options stay.</li></ul><p>Passwords for archives and WebDAV are stored in the settings file, readable only by your user account, but not encrypted.</p>',18)])])}const u=e(n,[["render",i]]);export{g as __pageData,u as default};
